const LOOP_TOGGLE = {
	STATE: true,
	BY_CLICK: false,
	BY_PRESS: false,
	BUTTON: " ",
	p5: null,
	updateState: () => {
		LOOP_TOGGLE.STATE = !LOOP_TOGGLE.STATE
	},
	toggle: () => {
		if (LOOP_TOGGLE.p5) {
			LOOP_TOGGLE.p5[LOOP_TOGGLE.STATE ? "loop" : "noLoop"]()
		} else {
			LOOP_TOGGLE.STATE ? loop() : noLoop()
		}
	},
}

const CLICK_TOGGLE_LIST = []
const PRESS_TOGGLE_LIST = []
const createToggle = (
	_btn,
	_func1,
	_func1Args = [],
	_func2,
	_func2Args = []
) => {
	let state = true
	const updateState = () => (state = !state)
	const toggle = () => {
		if (state) _func1(..._func1Args)
		else _func2(..._func2Args)
	}
	return { btn: _btn, updateState, toggle }
}

const CLICK_DO_LIST = []
const PRESS_DO_LIST = []
const createDo = (_btn, _func, _args = []) => {
	const run = () => {
		_func(..._args)
	}
	return { btn: _btn, run }
}

export const ClickLoopToggle = (_p5 = null) => {
	LOOP_TOGGLE.BY_CLICK = true
	LOOP_TOGGLE.p5 = _p5
}
export const ClickToggle = (_func1, _func2, _func1Args = [], _func2Args = []) => {
	CLICK_TOGGLE_LIST.push(
		createToggle("CLICK", _func1, _func1Args, _func2, _func2Args)
	)
}
export const ClickDo = (_func, _args = []) => {
	CLICK_DO_LIST.push(createDo("CLICK", _func, _args))
}
document.addEventListener("mousedown", () => {
	if (LOOP_TOGGLE.BY_CLICK) {
		LOOP_TOGGLE.updateState()
		LOOP_TOGGLE.toggle()
	}
	CLICK_TOGGLE_LIST.forEach((toggle) => {
		toggle.updateState()
		toggle.toggle()
	})
	CLICK_DO_LIST.forEach((item) => {
		item.run()
	})
})

export const PressLoopToggle = (_btn, _p5 = null) => {
	LOOP_TOGGLE.BY_PRESS = true
	LOOP_TOGGLE.BUTTON = _btn
	LOOP_TOGGLE.p5 = _p5
}
export const PressToggle = (
	_btn,
	_func1,
	_func2,
	_func1Args = [],
	_func2Args = []
) => {
	PRESS_TOGGLE_LIST.push(
		createToggle(_btn, _func1, _func1Args, _func2, _func2Args)
	)
}
export const PressDo = (_btn, _func, _args = []) => {
	PRESS_DO_LIST.push(createDo(_btn, _func, _args))
}
document.addEventListener("keydown", (event) => {
	const key = event.key
	if (key === LOOP_TOGGLE.BUTTON) {
		if (LOOP_TOGGLE.BY_PRESS) {
			LOOP_TOGGLE.updateState()
			LOOP_TOGGLE.toggle()
		}
	}
	PRESS_TOGGLE_LIST.forEach((toggle) => {
		if (key === toggle.btn) {
			toggle.updateState()
			toggle.toggle()
		}
	})
	PRESS_DO_LIST.forEach((item) => {
		if (key === item.btn) item.run()
	})
})

